<?php require_once __DIR__ . '/includes/functions.php'; $result=null; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $result=db_fetch('SELECT pc.*,p.full_name,p.phone,p.whatsapp FROM patient_cases pc JOIN patients p ON p.id=pc.patient_id WHERE pc.case_code=? AND (p.phone=? OR p.whatsapp=?)', [$_POST['case_code'],$_POST['phone'],$_POST['phone']]); if($result){ $result['order']=db_fetch('SELECT * FROM orders WHERE case_id=? ORDER BY id DESC LIMIT 1',[$result['id']]); $result['rx']=db_fetch('SELECT * FROM prescriptions WHERE case_id=? ORDER BY id DESC LIMIT 1',[$result['id']]); }} public_header('Track Case'); ?><section class="py-5"><div class="container"><div class="row g-4"><div class="col-lg-5"><div class="card soft-card"><div class="card-body"><h1>Track Case</h1><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Case ID</label><input name="case_code" class="form-control mb-3" required><label>Phone/WhatsApp</label><input name="phone" class="form-control mb-3" required><button class="btn btn-teal">Track</button></form></div></div></div><div class="col-lg-7"><?php if($_SERVER['REQUEST_METHOD']==='POST'): if($result): ?><div class="card soft-card"><div class="card-body"><h3><?= e($result['case_code']) ?></h3><p>Patient: <?= e($result['full_name']) ?></p><p>Case status: <strong><?= e($result['status']) ?></strong></p><p>Doctor status: <strong><?= e($result['doctor_status']) ?></strong></p><p>Order status: <strong><?= e($result['order']['status'] ?? 'No order') ?></strong></p><?php if(!empty($result['rx'])): ?><a class="btn btn-outline-success" href="admin/prescription-review.php?print=<?= (int)$result['rx']['id'] ?>">View Prescription</a><?php endif; ?></div></div><?php else: ?><?= empty_state('No matching case found.') ?><?php endif; endif; ?></div></div></div></section><?php public_footer(); ?>
